"""Export portable complete counters, identity receipts, API tables and report."""
import collections,hashlib,json,math,os,statistics,subprocess
from pathlib import Path
art=Path(os.environ['PEERS_ART']);root=Path(__file__).resolve().parents[2];dest=root/'parity/peers'
rows=[json.loads(s)for s in (art/'counts.jsonl').read_text().splitlines()];stage_rows=[json.loads(s)for s in (art/'stage-counts.jsonl').read_text().splitlines()]
assert len(rows)==840 and len(stage_rows)==162
ids=json.loads((art/'identities.json').read_text());stage_ids=json.loads((art/'stage-identities.json').read_text());inv=json.loads((dest/'inventory.json').read_text());meta=json.loads((art/'inputs.json').read_text());cases=[x['case']for x in meta];ops=json.loads((art/'campaign.json').read_text())['ops']
def med(case,op,arm,field='instructions_per_call',source=rows):return statistics.median(r[field]for r in source if (r['case'],r['op'],r['arm'])==(case,op,arm))
def ratio(case,op,arm):return med(case,op,arm)/med(case,op,'ours')
def gm(v):return math.exp(statistics.mean(math.log(x)for x in v))
def identity(case,op,arm,source=ids):return next(r for r in source if(r['case'],r['op'],r['arm'])==(case,op,arm))
def desc(r):
 if r['identity']=='byte-identical':return 'byte-identical'
 actual='end' if r['actual_byte'] is None else r['actual_byte']; expected='end' if r['cpp_byte'] is None else r['cpp_byte']
 return f"differs: byte {r['first_byte']}, {actual} vs {expected}; lengths {r['bytes']}/{r['cpp_bytes']}"
notes={'simplify':'Half index count; error 0.5; no flags/locks; includes returned f32 error.','simplify-attributes':'Four synthetic floats/vertex, unit weights; same target/error.','simplify-sloppy':'No locks; same target/error.','cache':'Default score preset.','overdraw':'Threshold 1.05; input order unchanged.','fetch':'12-byte vertices; peer in-place APIs require an index copy.','meshlets':'64/124/0; C++/optimesh four-byte triangle padding; normalized outside counters.','vertex-encode':'Version 1, level 2; explicit per-call setting.','vertex-decode':'Same C++ 1.3 stream; 12-byte vertices.','index-encode':'Version 1; u32 source.','index-decode':'Same C++ 1.3 stream; 32-bit result.','cluster-lod':'Ours/C++ only; raster defaults 128, positions only; callback record construction counted.'}
s=['# Peer comparison and C++ 1.3 feature inventory\n',
 'Entry: meshoptimizer-rs 0.2.13, commit 42782f5. Peers: meshopt 0.7.0 (vendored C++ 1.3), optimesh 1.1.0. No library changes.\n',
 'Metric: median of three instructions:u samples per cell, 100% counter running. Ratios are peer / ours: below 1 means the peer executes fewer user instructions. Corpus ratios are equal-case geometric means; each real-mesh column is one retained input. No wall-time performance conclusion.\n',
 f'Completed: {len(rows)} main samples, {len(stage_rows)} stage samples; 280 main and 54 stage outputs validated, 144 encoder/decoder cross-checks. Wall seconds/call and process peak RSS are disclosure only. All build/fixture/collection/validation jobs used CPU-only admission with 4 GB declared. Maximum measured process RSS: {max(r["peak_rss_kib"]for r in rows+stage_rows)} KiB.\n',
 'Both Rust ports enable SIMD; C++ uses its default native dispatch. All consumers use opt-level 3, thin LTO, one codegen unit and no target-cpu override. Ours uses std+simd+clusterlod and a 3 GiB Workspace storage cap; default counted-work limit. C++ uses the public ffi API, except the public cluster-LOD callback wrapper. These are allocating consumer calls, not a separate benchmark of meshopt idiomatic wrappers or Cargo default feature sets.\n',
 'All arms count output allocation, required copies, scratch and destruction after one warmup. Ours can retain Workspace capacity; neither peer exposes an equivalent scratch handle. Parsing, serialization, meshlet padding normalization and validation are outside counters. Cluster-LOD callback collection and a position clone are counted in both arms; the C++ wrapper additionally creates borrowed-cluster descriptor vectors per callback. These API costs are included, not subtracted.\n',
 'API adaptation: ours returns owned checked results and takes Workspace/views; C++/optimesh caller destinations are zero-initialized inside each counted call. Simplify result structs, tuples and C++ out-error pointers serialize to the same indices-plus-f32 record. Attributes use four float elements versus the peers’ 16-byte stride. optimesh index decode returns u32 elements; ours/C++ return four-byte element buffers, with serialization outside counters. Codec global index version is set once outside counters; ours selects it per call. The C++ cluster-LOD wrapper accepts immutable positions and rejects dilation, so shared raster defaults keep dilation disabled; ours’ callback returns Ok(id) where the peer returns id. These are the call-shape mismatches in the measured surface.\n',
 'The existing five corpus meshes and three real meshes are unchanged packed XYZ/index projections of retained inputs. The original real vertex layout is 64 bytes; all three arms use the same 12-byte XYZ layout here. Attribute calls use the existing four-float synthetic formula, not authored real attributes. No quality-equivalence, GPU, whole-chain throughput or strided-layout performance claim follows. The separate eighteen-stage supplement retains original simplify targets/errors and indices while using the same packed position projection.\n',
 'The first build failed with exit 101 on a callback return type and was corrected. The first collection stopped with harness exit 1 / child exit 101 at the default 1 GiB Workspace cap on real-214e attribute simplification. Its 535 finished samples and failed cell remain retained and are excluded in full. The final matrix was rebuilt and recollected with the explicit 3 GiB cap; no library limit or threshold changed.\n',
 '## Peer table\n',
 '| Function | Peer | Corpus ratio | real-214e | real-a082 | real-b6fd | Output vs C++ (identical/cases) | API/settings notes |',
 '|---|---|---:|---:|---:|---:|---|---|']
for op in ops:
 for arm in ['cpp','rust']if op!='cluster-lod'else ['cpp']:
  hits=sum(identity(c,op,arm)['identity']=='byte-identical'for c in cases)
  ours_hits=sum(identity(c,op,'ours')['identity']=='byte-identical'for c in cases)
  ratios=[f'{gm([ratio(c,op,arm)for c in cases[:5]]):.3f}']+[f'{ratio(c,op,arm):.3f}'for c in cases[5:]]
  s.append('| '+' | '.join([op,'meshopt'if arm=='cpp'else'optimesh',*ratios,f'ours {ours_hits}/8; peer {hits}/8',notes[op]])+' |')
s+=['\n## Eighteen retained simplify stages\n','Ratios below use sums of six stage instruction medians per chain. Settings come from each original stage manifest; repetitions are three per arm. Identity includes index bytes and reported error.\n','| Chain | meshopt / ours | optimesh / ours | Ours identity | optimesh identity |','|---|---:|---:|---|---|']
for chain in cases[5:]:
 cs=[x['case']for x in json.loads((art/'stage-inputs.json').read_text())if x['case'].startswith(chain+'-')]
 den=sum(med(c,'simplify','ours',source=stage_rows)for c in cs)
 values=[sum(med(c,'simplify',a,source=stage_rows)for c in cs)/den for a in ['cpp','rust']]
 hits=[sum(identity(c,'simplify',a,stage_ids)['identity']=='byte-identical'for c in cs)for a in ['ours','rust']]
 s.append(f'| {chain} | {values[0]:.3f} | {values[1]:.3f} | {hits[0]}/6 | {hits[1]}/6 |')
s+=['\n## Gaps ranked by user value\n',
 '1. Typed index/output adapters (M): asset importers with u16 topology and generic decoded storage can avoid manual conversions. C++ has templated index overloads; optimesh has typed codec output traits but u32 processing. Ours has 16/32-bit byte-width codec output and u32 processing; the typed facade is partial. This is API work, not a missing codec.\n',
 '2. Caller-defined cache score tables (S): expose cache-position and live-valence scores for engine/hardware tuning. optimesh exposes VertexScoreTable and optimize_vertex_cache_table. Ours exposes the default and strip presets only. Validate tuned tables against downstream cache/raster workloads before claiming benefit.\n',
 '3. Library-specific allocator hooks (L): hosts using arenas, per-library telemetry or allocator isolation can choose transient allocation separately from the application global allocator. C++ exposes setAllocator; neither Rust port does. Ours provides Workspace limits/retention, which is a different control.\n',
 'No core C++ geometry-processing function is missing by API name. Experimental normals/remesh and the two experimental simplify flags require the experimental feature; cluster LOD requires clusterlod. Global codec-version setters have explicit per-call equivalents and are not format gaps. Presence below is source/API coverage, not a new exhaustive parity proof over every option. S: local API/kernel extension; M: API/storage plumbing across families; L: new algorithm family or library-wide allocation/ownership refactor.\n',
 '## Output differences\n','All identities use complete little-endian outputs; simplify includes error, fetch includes indices and vertices, cluster LOD includes all callback records. First byte offsets are zero-based; null means end-of-buffer. Raw meshlet layout is checked separately from normalized packed topology.\n',
 '| Case | Function | Arm | Compared representation | First difference / identity |','|---|---|---|---|---|']
for r in ids+stage_ids:
 if r['identity']!='byte-identical':s.append(f"| {r['case']} | {r['op']} | {r['arm']} | canonical | {desc(r)} |")
 if 'raw'in r and r['raw']['identity']!='byte-identical':s.append(f"| {r['case']} | {r['op']} | {r['arm']} | raw layout | {desc(r['raw'])} |")
s+=['\n## Complete function inventory\n','C++ references are relative to the meshopt 0.7.0 crate; optimesh references are relative to optimesh 1.1.0. Port references are relative to this repository. The pinned source hashes and machine-readable rows are in inventory.json. Individual C++ template overloads and implicitly public Rust trait methods are included; cfg(test) helpers and private SIMD modules are excluded.\n','| Source surface/function | Source file:line | Port status | Port function/type and file:line | optimesh | Notes |','|---|---|---|---|---|---|']
for r in inv['functions']:
 note=r['note']
 if r['status']!='present'and r.get('does','-')!='-':note+=' '+r['does']+' Users: '+r['users']+' Size: '+r['size']+'.'
 s.append('| '+' | '.join([r['surface']+' '+r['symbol'],r['source'],r['status'],r['port']+'; '+r['port_source'],r['optimesh'],note]).replace('\n',' ')+' |')
s+=['\n## Complete option inventory\n','Includes named flags/enums, every clodConfig field, optimesh input/config fields and score-table controls, plus numeric/layout domains. Counts/strides are represented by checked views; optimesh attribute strides are bytes while ours uses float elements. Output/statistic/error fields are not options. optimesh error enum variants are retained in inventory.json for completeness. Cargo features: optimesh simd maps to ours simd; oracle/oracle-simd only enable test-oracle builds and are not runtime geometry options.\n','| Surface/option | Source file:line | Status | Port and file:line | optimesh | Notes |','|---|---|---|---|---|---|']
for r in inv['options']:s.append('| '+' | '.join([r['surface']+' '+r['symbol'],r['source'],r['status'],r['port']+'; '+r['port_source'],r['optimesh'],r['note']])+' |')
s+=['\n## Per-case measurements\n','Instructions and wall seconds/call are medians of three. RSS KiB is the maximum of three process peaks, including startup/warmup/serialization; it is not incremental algorithm memory. Each peer ratio uses that case/function\'s ours median. Per-repetition integer counters, elapsed times, RSS, hashes and binary bindings are in counts.jsonl and stage-counts.jsonl.\n','| Case | Function | Arm | Instructions/call | Ratio vs ours | Wall s/call | Peak RSS KiB | Output vs C++ |','|---|---|---|---:|---:|---:|---:|---|']
for source,identities in [(rows,ids),(stage_rows,stage_ids)]:
 for case,op,arm in dict.fromkeys((r['case'],r['op'],r['arm'])for r in source):
  inst=med(case,op,arm,source=source);rat=inst/med(case,op,'ours',source=source);wall=med(case,op,arm,'wall_seconds_per_call',source);rss=max(r['peak_rss_kib']for r in source if(r['case'],r['op'],r['arm'])==(case,op,arm))
  s.append(f'| {case} | {op} | {arm} | {inst:.3f} | {rat:.3f} | {wall:.9f} | {rss} | {desc(identity(case,op,arm,identities))} |')
s+=['\n## Evidence and reproduction\n','README.md gives the admitted build/prepare/measure/validate sequence. REGISTRATION.md fixes allocation policy and settings. binding.json seals source, binaries, input hashes, compiler/perf versions and CPU description. audit.json and receipts.json retain exit codes and raw-evidence hashes; cleanup.json binds deletion of the dedicated target. Full binaries, private assets, output buffers, raw perf/time logs, admission logs and excluded attempts remain in the retained scratch directory. No private paths or private names are required to inspect the public tables.\n']
(dest/'REPORT.md').write_text('\n'.join(s).rstrip()+'\n')
for name in ['counts.jsonl','stage-counts.jsonl','identities.json','stage-identities.json','inputs.json','stage-inputs.json','validation.json','stage-validation.json']:(dest/name).write_bytes((art/name).read_bytes())
binding=json.loads((art/'build-binding.json').read_text());binding['entry_commit']='42782f5b5088be0ce8aa34e80d1b1e6c8e3d665a';binding['perf']=json.loads((art/'campaign.json').read_text())['perf'];binding['cpu']=json.loads((art/'campaign.json').read_text())['cpu'];binding['cpu_model']=next(l.split(':',1)[1].strip()for l in Path('/proc/cpuinfo').read_text().splitlines()if l.startswith('model name'));binding['rustc']=subprocess.check_output(['rustc','--version'],text=True).strip();binding['cxx']=subprocess.check_output(['c++','--version'],text=True).splitlines()[0];binding['target']='x86_64-unknown-linux-gnu';binding['rustflags']=[];binding['scripts']={str(p.relative_to(root)):hashlib.sha256(p.read_bytes()).hexdigest()for p in dest.glob('*.py')};(dest/'binding.json').write_text(json.dumps(binding,indent=2)+'\n')
print('REPORT',len(rows)+len(stage_rows),'samples;',len(inv['functions']),'function rows;',len(inv['options']),'option rows')
